.bpi-widget {
    font-family: 'Roboto', sans-serif;
    padding: 16px;
}
.bpi-titulo {
    font-size: 15px;
    font-weight: 600;
    margin-bottom: 10px;
    color: rgba(0, 0, 0, 0.87);
}
.bpi-info {
    font-size: 13px;
