    font-weight: 600;
}
.bpi-separador {
    margin: 18px 0;
    border: none;
    border-top: 1px solid rgba(0, 0, 0, 0.12);
}
.bpi-boton-restaurar {
    background-color: #2E7D32;
}
.bpi-boton-restaurar:hover {
    background-color: #1b5e20;
}

descriptor.controllerScript:
// ============================================================
// Widget de UN SOLO USO para borrar el punto intruso de "caudal_fijado"
// en El Marchante (2026-09-21 11:26:19, valor 5.58) que rompia la recta
// del "Caudal Medio" de ese dia. Hace la misma llamada DELETE que se
// intento por Swagger, pero desde dentro de la propia web de ThingsBoard
// ($ctx.http), asi que no tiene el problema de host/CORS que daba Swagger
// (URL relativa -> mismo dominio que el navegador ya tiene abierto).
//
// AJUSTAR estas constantes si se quiere reutilizar para borrar OTRO punto
// (por ejemplo si aparece el mismo problema en otro dia o entidad):
// ============================================================
var ASSET_ID = 'ea8a5720-84c3-11f1-9a1a-412768cf7861'; // El Marchante (Grupo_Riego)
var CLAVE = 'caudal_fijado';
var START_TS = 1789982778000; // 2026-09-21 11:26:18 (margen de 1s antes)
var END_TS = 1789982780000;   // 2026-09-21 11:26:20 (margen de 1s despues)

// NUEVO -- el borrado "de 1 a 19" que se hizo desde la UI de ThingsBoard se
// llevo tambien por delante el punto bueno de las 00:00:00 del dia 21 (esa
// pantalla cuenta "hora 1" como el tramo 00:00-01:00, asi que el rango
// empezaba en realidad en medianoche). Hay que volver a crear ESE punto,
// con el MISMO valor que quedo en el de cierre (23:59:59 = 2.89), porque
// "caudal_fijado" son siempre dos puntos con el mismo valor.
var RESTAURAR_TS = 1789941600000; // 2026-09-21 00:00:00 (hora Madrid)
var RESTAURAR_VALOR = 2.89;

var $ctx, $container;

self.onInit = function () {
    $ctx = self.ctx;
    $container = $ctx.$container;

    $container.find('#bpi-clave').text(CLAVE);
    $container.find('#bpi-fecha').text(new Date(START_TS).toLocaleString('es-ES') + ' - ' + new Date(END_TS).toLocaleString('es-ES'));
    $container.find('#bpi-fecha-restaurar').text(new Date(RESTAURAR_TS).toLocaleString('es-ES'));
    $container.find('#bpi-valor-restaurar').text(RESTAURAR_VALOR + ' (mismo valor que el punto de las 23:59:59)');

    $container.find('#bpi-btn').on('click', function () {
        var $btn = $(this);
        var $msg = $container.find('#bpi-msg');
        var confirmado = confirm(
            'Vas a borrar el punto de "' + CLAVE + '" de El Marchante entre\n' +
            new Date(START_TS).toLocaleString('es-ES') + ' y ' + new Date(END_TS).toLocaleString('es-ES') + '.\n\n' +
            'Esta accion NO se puede deshacer. ¿Seguro?'
        );
        if (!confirmado) return;

        $btn.prop('disabled', true);
        $msg.text('Borrando...').css('color', '#1976d2');

        var url = '/api/plugins/telemetry/ASSET/' + ASSET_ID + '/timeseries/delete'
            + '?keys=' + encodeURIComponent(CLAVE)
            + '&deleteAllDataForKeys=false'
            + '&startTs=' + START_TS
            + '&endTs=' + END_TS
            + '&deleteLatest=false'
            + '&rewriteLatestIfDeleted=false';

        $ctx.http.delete(url).subscribe(
            function () {
                $msg.text('Borrado correctamente. Ya puedes comprobar la grafica de ese dia.').css('color', '#388e3c');
                $btn.prop('disabled', false);
            },
            function (err) {
                var detalle = (err && err.error && err.error.message) ? err.error.message : (err && err.message) ? err.message : JSON.stringify(err);
                $msg.text('Error al borrar: ' + detalle).css('color', '#d32f2f');
                $btn.prop('disabled', false);
            }
        );
    });

    $container.find('#bpi-btn-restaurar').on('click', function () {
        var $btn = $(this);
        var $msg = $container.find('#bpi-msg-restaurar');
        var confirmado = confirm(
            'Vas a volver a crear el punto de "' + CLAVE + '" de El Marchante en\n' +
            new Date(RESTAURAR_TS).toLocaleString('es-ES') + ' con valor ' + RESTAURAR_VALOR + '.\n\n' +
            '¿Seguro?'
        );
        if (!confirmado) return;

        $btn.prop('disabled', true);
        $msg.text('Restaurando...').css('color', '#1976d2');

        var url = '/api/plugins/telemetry/ASSET/' + ASSET_ID + '/timeseries/ANY';
        var payload = { ts: RESTAURAR_TS, values: {} };
        payload.values[CLAVE] = RESTAURAR_VALOR;

        $ctx.http.post(url, payload).subscribe(
            function () {
                $msg.text('Punto restaurado correctamente.').css('color', '#388e3c');
                $btn.prop('disabled', false);
            },
            function (err) {
                var detalle = (err && err.error && err.error.message) ? err.error.message : (err && err.message) ? err.message : JSON.stringify(err);
                $msg.text('Error al restaurar: ' + detalle).css('color', '#d32f2f');
                $btn.prop('disabled', false);
            }
        );
    });
};

self.onDataUpdated = function () {};
self.onResize = function () {};
self.onDestroy = function () {};

